#include <bits/stdc++.h>
using namespace std;
int day;
string s, cur(7, '0'), out;
int low[8], high[8];
long long cnt = 0;

// Depth-first in ascending digit order, pruned by the reachable hour range.
void visit(int i, int remaining) {
    if (remaining < low[i] || remaining > high[i]) return;
    if (i == 7) { out += cur; out += '\n'; cnt++; return; }
    if (s[i] == '?') {
        for (int v = 0; v <= day; v++) { cur[i] = '0' + v; visit(i + 1, remaining - v); }
    } else {
        cur[i] = s[i];
        visit(i + 1, remaining - (s[i] - '0'));
    }
}

