import java.io.*;
import java.util.*;

public class Main {
    static int day;
    static char[] s, cur = new char[7];
    static int[] low = new int[8], high = new int[8];
    static StringBuilder out = new StringBuilder();
    static int cnt = 0;

    // Depth-first in ascending digit order, pruned by the reachable hour range.
    static void visit(int i, int remaining) {
        if (remaining < low[i] || remaining > high[i]) return;
        if (i == 7) { out.append(cur).append('\n'); cnt++; return; }
        if (s[i] == '?') {
            for (int v = 0; v <= day; v++) { cur[i] = (char) ('0' + v); visit(i + 1, remaining - v); }
        } else {
            cur[i] = s[i];
            visit(i + 1, remaining - (s[i] - '0'));
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int work = Integer.parseInt(st.nextToken());
        day = Integer.parseInt(st.nextToken());
        String line = br.readLine();
        while (line.trim().isEmpty()) line = br.readLine();
        s = line.trim().toCharArray();
        for (int i = 6; i >= 0; i--) {
            low[i] = low[i + 1] + (s[i] == '?' ? 0 : s[i] - '0');
            high[i] = high[i + 1] + (s[i] == '?' ? day : s[i] - '0');
        }
        visit(0, work);
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out), 1 << 16));
        pw.println(cnt);
        pw.print(out);
        pw.flush();
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var (
	day       int
	s         string
	cur       = make([]byte, 7)
	low, high [8]int
	out       []byte
	cnt       int
)

// Depth-first in ascending digit order, pruned by the reachable hour range.
func visit(i, remaining int) {
	if remaining < low[i] || remaining > high[i] {
		return
	}
	if i == 7 {
		out = append(out, cur...)
		out = append(out, '\n')
		cnt++
		return
	}
	if s[i] == '?' {
		for v := 0; v <= day; v++ {
			cur[i] = byte('0' + v)
			visit(i+1, remaining-v)
		}
	} else {
		cur[i] = s[i]
		visit(i+1, remaining-int(s[i]-'0'))
	}
}

func main() {
	var work int
	fmt.Fscan(bufio.NewReader(os.Stdin), &work, &day, &s)
	for i := 6; i >= 0; i-- {
		if s[i] == '?' {
			low[i], high[i] = low[i+1], high[i+1]+day
		} else {
			d := int(s[i] - '0')
			low[i], high[i] = low[i+1]+d, high[i+1]+d
		}
	}
	visit(0, work)
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	fmt.Fprintln(w, cnt)
	w.Write(out)
}
